   "location": "Line and shaded area, 'Month vs. Number of samples tested'",
   "fact": "The blue line begins at the lowest point on the far left (Nov 20) and rises steadily toward the right, ending at its highest point on the far right (Jun 26). The shaded blue area fills the space between the line and the top of the plot."
  },
  {
   "location": "Y-axis, 'Count'",
   "fact": "The axis is inverted, with 0.0 at the top and 1.2 at the bottom, scaled by 1e6. A higher position on the chart corresponds to a lower count value."
  },
  {
   "location": "Line segment from Nov 20 to Oct 12",
   "fact": "The line shows a steep upward trajectory (visually moving from the bottom of the chart toward the middle), indicating a rapid change in the plotted value during this period."
  },
  {
   "location": "Line segment from Sep 7 to Jun 26",
   "fact": "The line continues to move upward (toward the top of the chart) but at a much shallower, more gradual slope compared to the earlier months."
  },
  {
   "location": "Rightmost data points (Jun 26, Jun 29, Jun 30)",
   "fact": "The line reaches its peak visual height at the far right, corresponding to the lowest numerical values on the inverted Y-axis (approximately 0.4e6)."
  },
  {
   "location": "Leftmost data point (Nov 20)",
   "fact": "The line starts at its lowest visual position, corresponding to the highest numerical value on the inverted Y-axis (approximately 1.25e6)."
  }
 ],
